using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Blog>(entity =>
        {
            // Breaking Change #1: EF 9 renamed "Discriminator" to "$type".
            // Existing documents use "Discriminator", so we must preserve it.
            entity.HasDiscriminator().HasJsonPropertyName("Discriminator");

            // Breaking Change #2: EF 9 changed id format from "EntityType|Key" to just "Key".
            // Existing documents use "Blog|1" format, so we opt back in.
            entity.HasPartitionKey(b => b.Id);
            entity.Property(b => b.Id)
                .HasJsonPropertyName("id")
                .ValueGeneratedNever();

            // Breaking Change #3: Cosmos DB does not support indexes defined by EF Core.
            // HasIndex() now throws at runtime in EF 9. Removed.
        });
    }

    protected override void ConfigureConventions(ModelConfigurationBuilder configurationBuilder)
    {
        // Breaking Change #2 fix: Restore the legacy "Discriminator|Key" id format
        // so existing documents are still found.
        configurationBuilder.Conventions.Add(_ => new IdConvention());
    }
}

