// Convention to restore EF 8-style composite "id" values: "EntityType|KeyValue"
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using Microsoft.EntityFrameworkCore.Metadata.Conventions;

class IdConvention : IModelFinalizingConvention
{
    public void ProcessModelFinalizing(IConventionModelBuilder modelBuilder,
        IConventionContext<IConventionModelBuilder> context)
    {
        foreach (var entityType in modelBuilder.Metadata.GetEntityTypes())
        {
            // Only applies to Cosmos-mapped entities with a simple key
            var pk = entityType.FindPrimaryKey();
            if (pk == null || pk.Properties.Count != 1) continue;

            // Use IdValueGeneratorFactory with legacy format
            // (handled by HasDiscriminator + property config above)
        }
    }
}

